import { useCallback, useId, useState, type KeyboardEvent } from 'react';
import { Input, Stack, Tag, Text } from '@jinx-ui/react';

type TagPickerProps = {
  label?: string;
  placeholder?: string;
  initialTags?: string[];
  maxTags?: number;
  onChange: (tags: string[]) => void;
};

function normalize(raw: string): string {
  return raw.trim().replace(/\s+/g, ' ');
}

export default function TagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
  maxTags = 10,
  onChange,
}: TagPickerProps) {
  const inputId = useId();
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (next: string[]) => {
      setTags(next);
      onChange(next);
    },
    [onChange],
  );

  const addTag = useCallback(
    (raw: string) => {
      const tag = normalize(raw);
      if (!tag || tags.length >= maxTags) return;
      if (tags.some((existing) => existing.toLowerCase() === tag.toLowerCase())) {
        setDraft('');
        return;
      }
      commit([...tags, tag]);
      setDraft('');
    },
    [commit, maxTags, tags],
  );

  const removeTag = useCallback(
    (tag: string) => {
      commit(tags.filter((existing) => existing !== tag));
    },
    [commit, tags],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      addTag(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      removeTag(tags[tags.length - 1]);
    }
  };

  const isFull = tags.length >= maxTags;

  return (
    <Stack direction="column" gap="var(--jx-space-3)">
      <Input
        id={inputId}
        label={label}
        placeholder={isFull ? 'Достигнут лимит тегов' : placeholder}
        value={draft}
        disabled={isFull}
        onChange={(event) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => addTag(draft)}
        aria-describedby={`${inputId}-hint`}
      />

      <Text id={`${inputId}-hint`} size="sm" tone="muted">
        {`Выбрано ${tags.length} из ${maxTags}. Enter или запятая — добавить тег.`}
      </Text>

      {tags.length > 0 && (
        <Stack
          direction="row"
          gap="var(--jx-space-2)"
          wrap
          role="list"
          aria-label="Выбранные теги"
        >
          {tags.map((tag) => (
            <Tag
              key={tag}
              role="listitem"
              removable
              onRemove={() => removeTag(tag)}
              aria-label={`Тег ${tag}`}
            >
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

